const fs=require("node:fs"),path=require("node:path"),crypto=require("node:crypto"),assert=require("node:assert/strict"),cp=require("node:child_process"),cwd="/Users/julianhein/.codex/worktrees/c9fb/r-dcc-units/dcc1";
assert.equal(process.cwd(),cwd);const prePath="docs/coordinator/worktree-completion/evidence/dcc1-284ada-preflight.json",pre=JSON.parse(fs.readFileSync(prePath)).record,root=pre.preservationRoot,sha=b=>crypto.createHash("sha256").update(b).digest("hex");
const info=p=>{const s=fs.lstatSync(p);assert(s.isFile()&&!s.isSymbolicLink(),p);const b=fs.readFileSync(p);return{path:p,bytes:b.length,sha256:sha(b),mode:s.mode&4095}};
assert(!fs.existsSync(root),root);for(const x of pre.oldCoverage)assert.deepEqual(info(x.path),x);
fs.mkdirSync(root,{mode:0o700});const copies=[];for(const x of pre.oldCoverage){const destination=path.join(root,x.path);assert(destination.startsWith(root+"/coverage/"));fs.mkdirSync(path.dirname(destination),{recursive:true,mode:0o700});fs.copyFileSync(x.path,destination,fs.constants.COPYFILE_EXCL);fs.chmodSync(destination,x.mode);const fd=fs.openSync(destination,"r");fs.fsyncSync(fd);fs.closeSync(fd);assert.deepEqual(info(destination),{...x,path:destination});assert.deepEqual(info(x.path),x);copies.push({...x,preservedPath:destination});}
function walk(p){const s=fs.lstatSync(p);assert(!s.isSymbolicLink(),p);if(s.isFile())return[p];assert(s.isDirectory());return fs.readdirSync(p).sort().flatMap(x=>walk(path.join(p,x)));}
assert.deepEqual(walk(root).sort(),copies.map(x=>x.preservedPath).sort());const fd=fs.openSync(root,"r");fs.fsyncSync(fd);fs.closeSync(fd);
const paths=copies.map(x=>x.preservedPath),ig=cp.spawnSync("git",["check-ignore","-v","-z","--stdin"],{cwd,input:paths.join("\0")+"\0",encoding:"utf8"});assert([0,1].includes(ig.status));const ip=ig.stdout.split("\0");assert.equal(ip.pop(),"");assert.equal(ip.length%4,0);const ignore=[];for(let i=0;i<ip.length;i+=4)ignore.push({source:ip[i],line:ip[i+1],pattern:ip[i+2],path:ip[i+3]});assert.equal(new Set(ignore.map(x=>x.path)).size,ignore.length);assert(ignore.every(x=>paths.includes(x.path)));
process.stdout.write(JSON.stringify({at:new Date().toISOString(),pass:true,classification:"Exclusive verified preservation copies of old coverage output; originals untouched by this copy operation; normal coverage may subsequently regenerate originals",root,preflight:info(prePath),copies,ignoreProvenance:ignore,visibleCopies:paths.filter(x=>!ignore.some(y=>y.path===x)),files:copies.length})+"\n");
